/* Risdel Books Module 00 - Foundation Schema | SQL Server */
SET XACT_ABORT ON;
BEGIN TRANSACTION;
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='system') EXEC('CREATE SCHEMA system');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='auth') EXEC('CREATE SCHEMA auth');
IF NOT EXISTS (SELECT 1 FROM sys.schemas WHERE name='audit') EXEC('CREATE SCHEMA audit');
IF OBJECT_ID('system.Companies') IS NULL CREATE TABLE system.Companies(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,Code nvarchar(20) NOT NULL UNIQUE,Name nvarchar(200) NOT NULL,TradingName nvarchar(200) NULL,RegistrationNumber nvarchar(100) NULL,TaxNumber nvarchar(100) NULL,Email nvarchar(200) NULL,Phone nvarchar(50) NULL,AddressLine1 nvarchar(250) NULL,AddressLine2 nvarchar(250) NULL,City nvarchar(100) NULL,State nvarchar(100) NULL,Country nvarchar(100) NOT NULL DEFAULT 'Nigeria',CurrencyCode char(3) NOT NULL DEFAULT 'NGN',TimeZone nvarchar(100) NOT NULL DEFAULT 'Africa/Lagos',LogoPath nvarchar(500) NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NULL);
IF OBJECT_ID('system.Branches') IS NULL CREATE TABLE system.Branches(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,CompanyId uniqueidentifier NOT NULL,Code nvarchar(20) NOT NULL,Name nvarchar(150) NOT NULL,BranchType nvarchar(50) NULL,Email nvarchar(200) NULL,Phone nvarchar(50) NULL,Address nvarchar(300) NULL,City nvarchar(100) NULL,State nvarchar(100) NULL,IsHeadOffice bit NOT NULL DEFAULT 0,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NULL,CONSTRAINT FK_Branches_Company FOREIGN KEY(CompanyId) REFERENCES system.Companies(Id),CONSTRAINT UQ_Branches_Company_Code UNIQUE(CompanyId,Code));
IF OBJECT_ID('system.Warehouses') IS NULL CREATE TABLE system.Warehouses(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,BranchId uniqueidentifier NOT NULL,Code nvarchar(20) NOT NULL,Name nvarchar(150) NOT NULL,WarehouseType nvarchar(50) NULL,Address nvarchar(300) NULL,AllowSales bit NOT NULL DEFAULT 1,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NULL,CONSTRAINT FK_Warehouses_Branch FOREIGN KEY(BranchId) REFERENCES system.Branches(Id),CONSTRAINT UQ_Warehouses_Branch_Code UNIQUE(BranchId,Code));
IF OBJECT_ID('auth.Users') IS NULL CREATE TABLE auth.Users(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,Email nvarchar(256) NOT NULL UNIQUE,DisplayName nvarchar(150) NOT NULL,PasswordHash nvarchar(500) NULL,MustChangePassword bit NOT NULL DEFAULT 1,FailedLoginCount int NOT NULL DEFAULT 0,LockedUntil datetime2 NULL,LastLoginAt datetime2 NULL,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),UpdatedAt datetime2 NULL);
IF OBJECT_ID('auth.Roles') IS NULL CREATE TABLE auth.Roles(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,Code nvarchar(80) NOT NULL UNIQUE,Name nvarchar(120) NOT NULL,Description nvarchar(500) NULL,IsSystem bit NOT NULL DEFAULT 0,IsActive bit NOT NULL DEFAULT 1,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('auth.Permissions') IS NULL CREATE TABLE auth.Permissions(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,PermissionKey nvarchar(180) NOT NULL UNIQUE,Module nvarchar(80) NOT NULL,Name nvarchar(150) NOT NULL,Description nvarchar(500) NULL,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('auth.UserRoles') IS NULL CREATE TABLE auth.UserRoles(UserId uniqueidentifier NOT NULL,RoleId uniqueidentifier NOT NULL,AssignedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),AssignedBy uniqueidentifier NULL,CONSTRAINT PK_UserRoles PRIMARY KEY(UserId,RoleId),CONSTRAINT FK_UserRoles_User FOREIGN KEY(UserId) REFERENCES auth.Users(Id),CONSTRAINT FK_UserRoles_Role FOREIGN KEY(RoleId) REFERENCES auth.Roles(Id));
IF OBJECT_ID('auth.RolePermissions') IS NULL CREATE TABLE auth.RolePermissions(RoleId uniqueidentifier NOT NULL,PermissionId uniqueidentifier NOT NULL,GrantedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),CONSTRAINT PK_RolePermissions PRIMARY KEY(RoleId,PermissionId),CONSTRAINT FK_RolePermissions_Role FOREIGN KEY(RoleId) REFERENCES auth.Roles(Id),CONSTRAINT FK_RolePermissions_Permission FOREIGN KEY(PermissionId) REFERENCES auth.Permissions(Id));
IF OBJECT_ID('system.SystemSettings') IS NULL CREATE TABLE system.SystemSettings(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,Category nvarchar(80) NOT NULL,SettingKey nvarchar(150) NOT NULL,SettingValue nvarchar(max) NULL,DataType nvarchar(30) NOT NULL DEFAULT 'string',Description nvarchar(500) NULL,IsEncrypted bit NOT NULL DEFAULT 0,UpdatedAt datetime2 NULL,CONSTRAINT UQ_SystemSettings_Key UNIQUE(Category,SettingKey));
IF OBJECT_ID('system.NumberSequences') IS NULL CREATE TABLE system.NumberSequences(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,SequenceKey nvarchar(80) NOT NULL UNIQUE,Prefix nvarchar(30) NOT NULL,CurrentNumber bigint NOT NULL DEFAULT 0,Padding int NOT NULL DEFAULT 6,ResetRule nvarchar(30) NOT NULL DEFAULT 'YEARLY',UpdatedAt datetime2 NULL);
IF OBJECT_ID('system.Notifications') IS NULL CREATE TABLE system.Notifications(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,UserId uniqueidentifier NULL,Title nvarchar(180) NOT NULL,Message nvarchar(1000) NOT NULL,Type nvarchar(40) NOT NULL DEFAULT 'INFO',Priority nvarchar(20) NOT NULL DEFAULT 'NORMAL',Link nvarchar(500) NULL,IsRead bit NOT NULL DEFAULT 0,CreatedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME(),ReadAt datetime2 NULL);
IF OBJECT_ID('system.Documents') IS NULL CREATE TABLE system.Documents(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,EntityType nvarchar(100) NOT NULL,EntityId uniqueidentifier NOT NULL,FileName nvarchar(260) NOT NULL,OriginalFileName nvarchar(260) NOT NULL,MimeType nvarchar(150) NOT NULL,FileSize bigint NOT NULL,StoragePath nvarchar(700) NOT NULL,UploadedBy uniqueidentifier NULL,UploadedAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('audit.AuditLogs') IS NULL CREATE TABLE audit.AuditLogs(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,UserId uniqueidentifier NULL,Action nvarchar(50) NOT NULL,Module nvarchar(80) NOT NULL,EntityType nvarchar(100) NULL,EntityId uniqueidentifier NULL,Description nvarchar(1000) NULL,OldValues nvarchar(max) NULL,NewValues nvarchar(max) NULL,IpAddress nvarchar(64) NULL,UserAgent nvarchar(500) NULL,BranchId uniqueidentifier NULL,OccurredAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
IF OBJECT_ID('audit.LoginHistory') IS NULL CREATE TABLE audit.LoginHistory(Id uniqueidentifier NOT NULL DEFAULT NEWSEQUENTIALID() PRIMARY KEY,UserId uniqueidentifier NULL,Email nvarchar(256) NOT NULL,WasSuccessful bit NOT NULL,FailureReason nvarchar(200) NULL,IpAddress nvarchar(64) NULL,UserAgent nvarchar(500) NULL,OccurredAt datetime2 NOT NULL DEFAULT SYSUTCDATETIME());
COMMIT TRANSACTION;
